import{_ as e,o as t,c as i,a2 as s}from"./chunks/framework.D3fmyz3M.js";const u=JSON.parse('{"title":"迁移路线","description":"从单体或旧系统渐进迁移到微前端，且随时可回滚。","frontmatter":{"title":"迁移路线","description":"从单体或旧系统渐进迁移到微前端，且随时可回滚。"},"headers":[],"relativePath":"mastery/migration.md","filePath":"mastery/migration.md","lastUpdated":1792674288000}'),n={name:"mastery/migration.md"};function l(r,a,d,p,o,h){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="迁移路线" tabindex="-1">迁移路线 <a class="header-anchor" href="#迁移路线" aria-label="Permalink to &quot;迁移路线&quot;">​</a></h1><p>迁移的目标不是“一次拆完”，而是“<strong>每一步都可回滚、每一步都有收益</strong>”。</p><h2 id="四种迁移策略" tabindex="-1">四种迁移策略 <a class="header-anchor" href="#四种迁移策略" aria-label="Permalink to &quot;四种迁移策略&quot;">​</a></h2><h3 id="_1-新老共存-推荐起点" tabindex="-1">1. 新老共存（推荐起点） <a class="header-anchor" href="#_1-新老共存-推荐起点" aria-label="Permalink to &quot;1. 新老共存（推荐起点）&quot;">​</a></h3><p>主应用保留，新功能用子应用接入：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/legacy/*  → 旧系统（iframe 或直接跳转）</span></span>
<span class="line"><span>/order/*   → 新订单子应用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>优点：风险最低，老系统不动。</p><h3 id="_2-路由分流" tabindex="-1">2. 路由分流 <a class="header-anchor" href="#_2-路由分流" aria-label="Permalink to &quot;2. 路由分流&quot;">​</a></h3><p>按路由把流量切到新应用：</p><div class="language-nginx vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">location</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> /order/ </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  proxy_pass </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://new-order/;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>适合新应用已经能独立承接完整业务域的情况。</p><h3 id="_3-页面级替换" tabindex="-1">3. 页面级替换 <a class="header-anchor" href="#_3-页面级替换" aria-label="Permalink to &quot;3. 页面级替换&quot;">​</a></h3><p>同一个页面里，部分模块先替换：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>订单详情页（旧）</span></span>
<span class="line"><span>  ├── 订单头（新子应用）</span></span>
<span class="line"><span>  ├── 商品明细（旧）</span></span>
<span class="line"><span>  └── 操作日志（新子应用）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>需要主应用具备组合能力，适合 qiankun / micro-app / Module Federation。</p><h3 id="_4-组件级替换" tabindex="-1">4. 组件级替换 <a class="header-anchor" href="#_4-组件级替换" aria-label="Permalink to &quot;4. 组件级替换&quot;">​</a></h3><p>只替换 UI 组件，不改变页面归属。适合 Web Components 或 Module Federation。</p><h2 id="迁移步骤" tabindex="-1">迁移步骤 <a class="header-anchor" href="#迁移步骤" aria-label="Permalink to &quot;迁移步骤&quot;">​</a></h2><h3 id="第一步-盘点" tabindex="-1">第一步：盘点 <a class="header-anchor" href="#第一步-盘点" aria-label="Permalink to &quot;第一步：盘点&quot;">​</a></h3><ul><li>业务域与页面清单。</li><li>技术栈与依赖。</li><li>流量与核心链路。</li><li>团队边界与发布节奏。</li></ul><h3 id="第二步-切边界" tabindex="-1">第二步：切边界 <a class="header-anchor" href="#第二步-切边界" aria-label="Permalink to &quot;第二步：切边界&quot;">​</a></h3><p>按业务域切，而不是按页面数量切。输出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>订单域：订单列表、详情、退款</span></span>
<span class="line"><span>商品域：商品管理、库存</span></span>
<span class="line"><span>公共域：登录、权限、布局</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="第三步-搭基座" tabindex="-1">第三步：搭基座 <a class="header-anchor" href="#第三步-搭基座" aria-label="Permalink to &quot;第三步：搭基座&quot;">​</a></h3><p>主应用只做四件事：</p><ol><li>布局与导航。</li><li>路由调度。</li><li>登录与权限。</li><li>监控与降级。</li></ol><h3 id="第四步-接第一个子应用" tabindex="-1">第四步：接第一个子应用 <a class="header-anchor" href="#第四步-接第一个子应用" aria-label="Permalink to &quot;第四步：接第一个子应用&quot;">​</a></h3><p>选择标准：</p><ul><li>边界清晰。</li><li>流量中等。</li><li>可回滚。</li><li>团队愿意配合。</li></ul><p>不要选核心交易主链路做第一个。</p><h3 id="第五步-打通基建" tabindex="-1">第五步：打通基建 <a class="header-anchor" href="#第五步-打通基建" aria-label="Permalink to &quot;第五步：打通基建&quot;">​</a></h3><ul><li>CI/CD。</li><li>版本清单。</li><li>监控与日志。</li><li>灰度与回滚。</li><li>契约与规范。</li></ul><h3 id="第六步-扩面" tabindex="-1">第六步：扩面 <a class="header-anchor" href="#第六步-扩面" aria-label="Permalink to &quot;第六步：扩面&quot;">​</a></h3><p>每接一个子应用，复盘一次：</p><ul><li>加载耗时是否达标？</li><li>是否有样式冲突？</li><li>通信契约是否清晰？</li><li>回滚是否演练过？</li></ul><h2 id="技术栈迁移示例" tabindex="-1">技术栈迁移示例 <a class="header-anchor" href="#技术栈迁移示例" aria-label="Permalink to &quot;技术栈迁移示例&quot;">​</a></h2><h3 id="vue-2-老系统-→-vue-3-新系统" tabindex="-1">Vue 2 老系统 → Vue 3 新系统 <a class="header-anchor" href="#vue-2-老系统-→-vue-3-新系统" aria-label="Permalink to &quot;Vue 2 老系统 → Vue 3 新系统&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主应用（Vue 3）</span></span>
<span class="line"><span>  ├── /legacy/* → Vue 2 子应用（qiankun 或 iframe）</span></span>
<span class="line"><span>  └── /order/*  → Vue 3 子应用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Vue 2 子应用只需导出生命周期，不需要重写。</p><h3 id="jquery-老系统" tabindex="-1">jQuery 老系统 <a class="header-anchor" href="#jquery-老系统" aria-label="Permalink to &quot;jQuery 老系统&quot;">​</a></h3><ul><li>iframe：改造成本最低。</li><li>qiankun：需要把 jQuery 页面包装成 HTML Entry，注意全局变量。</li><li>wujie：侵入较小。</li></ul><h3 id="多技术栈共存" tabindex="-1">多技术栈共存 <a class="header-anchor" href="#多技术栈共存" aria-label="Permalink to &quot;多技术栈共存&quot;">​</a></h3><ul><li>qiankun / micro-app：运行时挂载，框架无关。</li><li>Module Federation：组件级共享，需要构建体系支持。</li></ul><h2 id="数据与状态迁移" tabindex="-1">数据与状态迁移 <a class="header-anchor" href="#数据与状态迁移" aria-label="Permalink to &quot;数据与状态迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>迁移方式</th></tr></thead><tbody><tr><td>登录态</td><td>主应用统一管理，props 注入</td></tr><tr><td>用户信息</td><td>主应用请求，子应用只读</td></tr><tr><td>权限</td><td>主应用下发 <code>can(action)</code></td></tr><tr><td>业务缓存</td><td>各子应用独立，避免共享可变对象</td></tr><tr><td>全局配置</td><td>配置中心或全局状态</td></tr></tbody></table><p>不要在两个应用之间直接共享可变对象。共享数据要经过明确的接口。</p><h2 id="回滚设计" tabindex="-1">回滚设计 <a class="header-anchor" href="#回滚设计" aria-label="Permalink to &quot;回滚设计&quot;">​</a></h2><p>每个阶段都要能回滚：</p><table tabindex="0"><thead><tr><th>阶段</th><th>回滚方式</th></tr></thead><tbody><tr><td>新子应用接入</td><td>路由切回旧页面</td></tr><tr><td>版本升级</td><td>清单改回旧版本</td></tr><tr><td>基座升级</td><td>主应用回滚构建</td></tr><tr><td>灰度</td><td>关闭开关</td></tr></tbody></table><p>回滚要能在 5 分钟内完成，并且不需要重新构建。</p><h2 id="迁移检查表" tabindex="-1">迁移检查表 <a class="header-anchor" href="#迁移检查表" aria-label="Permalink to &quot;迁移检查表&quot;">​</a></h2><ul><li>[ ] 业务边界已确认，且有负责人。</li><li>[ ] 主应用只承担基座职责。</li><li>[ ] 子应用可独立运行、独立部署。</li><li>[ ] 通信契约有类型定义。</li><li>[ ] 样式与全局变量无污染。</li><li>[ ] 路由刷新可用。</li><li>[ ] 监控包含子应用维度。</li><li>[ ] 灰度与回滚已演练。</li><li>[ ] 老系统退出计划已明确。</li></ul><h2 id="常见失败原因" tabindex="-1">常见失败原因 <a class="header-anchor" href="#常见失败原因" aria-label="Permalink to &quot;常见失败原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原因</th><th>表现</th><th>对策</th></tr></thead><tbody><tr><td>边界按页面切</td><td>联调成本高</td><td>按业务域重切</td></tr><tr><td>基座承载业务</td><td>主应用越来越重</td><td>业务下沉到子应用</td></tr><tr><td>只集成不治理</td><td>上线后故障多</td><td>先补监控与回滚</td></tr><tr><td>共享可变状态</td><td>互相影响</td><td>改为 props / 事件</td></tr><tr><td>没有退出计划</td><td>新老长期并存</td><td>设定老系统下线时间</td></tr></tbody></table><p>下一篇：<a href="/micro-frontend-docs/mastery/troubleshooting">故障手册</a>。</p>`,55)])])}const b=e(n,[["render",l]]);export{u as __pageData,b as default};
